do $$
declare n int;
begin
  select count(*) into n from public.memes m join t_batch b on b.id=m.id
   where m.media_type='image' and m.category in ('phrase','comment') and m.origin_kind<>'house_original'
     and not exists (select 1 from public.meme_contents c where c.meme_id=m.id and c.availability='live' and c.moderation_status='approved');
  if n <> 872 then raise exception 'Lane T preflight expected 872, matched %', n; end if;
  update public.memes m set media_type='text' from t_batch b where m.id=b.id and m.media_type='image';
  get diagnostics n = row_count;
  if n <> 872 then raise exception 'Lane T update expected 872, affected %', n; end if;
end $$;
commit;
